<script setup lang="ts">
import {computed,onBeforeUnmount,onMounted,ref} from 'vue';
import {formatCredits} from '@new-game/domain';
import {kenoTicketRows} from './keno-ticket';
const props=defineProps<{picks:number[];drawn:number[];stake:string;staked:boolean;complete:boolean;reducedMotion:boolean}>();
const emit=defineEmits<{close:[]}>();
const dialog=ref<HTMLDialogElement>();
const rows=computed(()=>kenoTicketRows(props.picks.length,props.stake));
const hits=computed(()=>props.picks.filter(n=>props.drawn.includes(n)).length);
const ordered=computed(()=>[...props.picks].sort((a,b)=>a-b));
let previous:HTMLElement|null=null;
onMounted(()=>{previous=document.activeElement as HTMLElement|null;dialog.value?.showModal();});
onBeforeUnmount(()=>{dialog.value?.close();if(previous?.isConnected)previous.focus({preventScroll:true});});
</script>
<template><Teleport to="body"><dialog ref="dialog" class="keno-ticket-dialog" :class="{'ticket-still':reducedMotion}" aria-labelledby="ticket-title" @keydown.esc.stop @cancel.prevent="emit('close')" @click="event=>{if(event.target===dialog)emit('close');}">
 <header><div><small>YOUR KENO TICKET</small><h2 id="ticket-title">{{picks.length}} picks · {{drawn.length}} / 20 drawn</h2></div><button autofocus aria-label="Close ticket" @click="emit('close')">✕</button></header>
 <div class="ticket-content"><section aria-label="Selected numbers"><h3>Your numbers <small>{{hits}} matched</small></h3><div class="ticket-numbers"><span v-for="n in ordered" :key="n" :class="{hit:drawn.includes(n)}">{{n}}<small v-if="drawn.includes(n)" aria-label="matched">✓</small></span><p v-if="!picks.length">Choose 4–10 numbers or use Quick Pick.</p></div><p>Marked numbers matched this draw. Unmarked numbers are your remaining picks.</p><p>{{staked?'Selected stake':'Preview stake'}}: <strong>{{formatCredits(stake)}}</strong> · Returns below include the stake.</p><p>Each draw reveals twenty numbers. Quick Pick and patterns only choose your ticket; they do not improve your chances.</p></section>
 <section aria-label="Ticket paytable"><h3>Return for {{picks.length}} picks</h3><table v-if="rows.length"><thead><tr><th>Matches</th><th>Multiplier</th><th>Credits returned</th></tr></thead><tbody><tr v-for="row in rows" :key="row.hits" :class="{current:complete&&row.hits===hits}"><th scope="row">{{row.hits}} <span v-if="complete&&row.hits===hits">← matches</span></th><td>{{row.multiplier}}×</td><td>{{formatCredits(row.award)}}</td></tr></tbody></table><p v-else>Select at least four numbers to see your paytable.</p><p v-if="!complete&&drawn.length">Draw in progress. A highlighted number is a match, not a settled award.</p></section></div>
 <footer>Paytable at the selected stake · Saved awards are in History. See Rules for the current paying-round setting.</footer>
</dialog></Teleport></template>
<style scoped>
.keno-ticket-dialog{width:min(760px,calc(100vw - 24px));max-height:calc(100dvh - 24px);box-sizing:border-box;padding:0;color:#f3efff;background:#181329;border:1px solid #a589d7;border-radius:20px;box-shadow:0 20px 90px #0009;overflow:auto;font:15px/1.5 system-ui}.keno-ticket-dialog::backdrop{background:#060412cc}.keno-ticket-dialog header{position:sticky;top:0;z-index:1;display:flex;align-items:center;justify-content:space-between;gap:12px;padding:16px 22px;background:#211a37;border-bottom:1px solid #736182}.keno-ticket-dialog header small{color:#e0c39b;letter-spacing:2px;font-size:11px}.keno-ticket-dialog h2{font-size:22px;margin:3px 0}.keno-ticket-dialog button{width:48px;height:48px;flex:none;border:1px solid #a589d7;border-radius:50%;background:#332644;color:#fff;cursor:pointer}.keno-ticket-dialog button:focus-visible{outline:3px solid #ffe59f;outline-offset:2px}.ticket-content{display:grid;grid-template-columns:1fr 1fr;gap:24px;padding:4px 22px 18px}.ticket-content h3{font-size:16px;display:flex;justify-content:space-between;gap:10px}.ticket-content h3 small{font-size:13px;font-weight:400;color:#ddd0f3}.ticket-content p{color:#c9c2d9;font-size:13px}.ticket-numbers{display:flex;gap:8px;flex-wrap:wrap;min-height:48px}.ticket-numbers>span{position:relative;display:grid;place-items:center;width:44px;height:44px;border:1px solid #837498;border-radius:12px;font-weight:700;background:#2a223c}.ticket-numbers>span.hit{border-color:#ffe8a4;color:#24192c;background:#ffe2a1}.ticket-numbers small{position:absolute;top:-6px;right:-3px;background:#fff;border-radius:50%;width:17px;height:17px;font-size:11px;text-align:center}.ticket-content table{width:100%;border-collapse:collapse;font-size:14px;font-variant-numeric:tabular-nums}.ticket-content td,.ticket-content th{padding:7px 6px;border-bottom:1px solid #51445d;text-align:right}.ticket-content th:first-child{text-align:left}.ticket-content thead{color:#c9c2d9;font-size:11px}.ticket-content tr.current{background:#533c67;color:#fff2b9}.ticket-content th span{font-size:10px}.keno-ticket-dialog footer{padding:12px 22px;border-top:1px solid #51445d;color:#c9c2d9;font-size:12px}@media(max-width:560px){.ticket-content{grid-template-columns:1fr;gap:0}.keno-ticket-dialog h2{font-size:19px}}@media(prefers-reduced-motion:no-preference){.keno-ticket-dialog[open]:not(.ticket-still){animation:ticket-enter .18s ease-out}@keyframes ticket-enter{from{opacity:0;transform:translateY(8px)}to{opacity:1;transform:translateY(0)}}}
</style>
